if(empty($serials))$serials=[($item['barcode']?:($item['sku']?:('ITEM'.$item_id)))];
function code39_svg(string $value): string {
    $patterns=['0'=>'nnnwwnwnn','1'=>'wnnwnnnnw','2'=>'nnwwnnnnw','3'=>'wnwwnnnnn','4'=>'nnnwwnnnw','5'=>'wnnwwnnnn','6'=>'nnwwwnnnn','7'=>'nnnwnnwnw','8'=>'wnnwnnwnn','9'=>'nnwwnnwnn','A'=>'wnnnnwnnw','B'=>'nnwnnwnnw','C'=>'wnwnnwnnn','D'=>'nnnnwwnnw','E'=>'wnnnwwnnn','F'=>'nnwnwwnnn','G'=>'nnnnnwwnw','H'=>'wnnnnwwnn','I'=>'nnwnnwwnn','J'=>'nnnnwwwnn','K'=>'wnnnnnnww','L'=>'nnwnnnnww','M'=>'wnwnnnnwn','N'=>'nnnnwnnww','O'=>'wnnnwnnwn','P'=>'nnwnwnnwn','Q'=>'nnnnnnwww','R'=>'wnnnnnwwn','S'=>'nnwnnnwwn','T'=>'nnnnwnwwn','U'=>'wwnnnnnnw','V'=>'nwwnnnnnw','W'=>'wwwnnnnnn','X'=>'nwnnwnnnw','Y'=>'wwnnwnnnn','Z'=>'nwwnwnnnn','-'=>'nwnnnnwnw','.'=>'wwnnnnwnn',' '=>'nwwnnnwnn','*'=>'nwnnwnwnn'];
    $value=strtoupper(preg_replace('/[^A-Z0-9\-\. ]/','-', $value));$value='*'.$value.'*';$x=10;$bars='';$unit=2;
    foreach(str_split($value) as $char){$pattern=$patterns[$char]??$patterns['-'];for($i=0;$i<9;$i++){ $w=($pattern[$i]==='w'?3:1)*$unit;if($i%2===0)$bars.='<rect x="'.$x.'" y="0" width="'.$w.'" height="60" fill="#000"/>'; $x+=$w;}$x+=$unit;}
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '.($x+10).' 78" role="img" aria-label="'.$value.'">'.$bars.'<text x="'.(($x+10)/2).'" y="74" text-anchor="middle" font-family="Arial" font-size="10">'.$value.'</text></svg>';
}
